import{_ as t,o as n,c as a,a2 as r}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"钉钉","description":"","frontmatter":{},"headers":[],"relativePath":"experience/dingding.md","filePath":"experience/dingding.md","lastUpdated":null}'),p={name:"experience/dingding.md"};function i(o,e,d,s,_,c){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="钉钉" tabindex="-1">钉钉 <a class="header-anchor" href="#钉钉" aria-label="Permalink to &quot;钉钉&quot;">​</a></h1><p>2014年，阿里经历了强推社交产品“来往”的巨大挫折，在智能手机全国开始普及的年代，因为社交用户基数大，而且极度高频的入口级特性，社交产品所能带来的安全感是各大互联网厂商都极度渴望的，所以你可以理解为什么马化腾会把微信横空出世称为：<strong>抢到第一张移动互联网船票</strong>。</p><p>绝望会让一个人抛弃原有的脑子里对世界所有的理解，进入一种<strong>彻底放空和内省状态</strong>，这时候才能静下心来观察和阅读世界真正的需要。</p><p>作为一个产品经理可能会反思，任何大而广的东西一定有弱点，如果说微信的社交面是一条横线，需要观察寻找的，是哪里可以诞生一条尚未挖掘的纵线。</p><p>静心向内看就会有答案，那就是阿里生态圈的万千小B企业，如果你进入用户的心中去“观察”他们的想法。你就会用心眼看到后面的答案。</p><p>钉钉的成功最深处，是在碎片化办公的大环境下，人性中饱含的对深度工作专注和效率的追求。而在这一点上，无论是老板还是员工，只要他还算是 “想做事的人” 那就是共通的！</p><p>钉钉所有的员工，入职后第一课就是被要求，放下已知，带着空杯进入那些小B企业中，同工同吃，“观察”和阅读用户内心真正的需要。</p>',7)])])}const m=t(p,[["render",i]]);export{g as __pageData,m as default};
